<?php
$assignments=$pdo->query("SELECT wa.*,jwc.name component_name,j.job_code,wp.display_name FROM work_assignments wa JOIN job_work_components jwc ON jwc.id=wa.job_work_component_id JOIN jobs j ON j.id=jwc.job_id LEFT JOIN worker_profiles wp ON wp.id=wa.worker_profile_id ORDER BY COALESCE(wa.offered_at,wa.created_at) DESC LIMIT 250")->fetchAll(PDO::FETCH_ASSOC);$workers=$pdo->query("SELECT id,display_name FROM worker_profiles WHERE status='active' AND compensation_policy IN ('rules','nonpayable','owner_no_pay') ORDER BY display_name")->fetchAll(PDO::FETCH_ASSOC);$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?>
<div class="pa-table-wrap"><table class="pa-table"><thead><tr><th>Job / work</th><th>Worker</th><th>Expected pay</th><th>Status</th><th class="text-right">Action</th></tr></thead><tbody><?php foreach($assignments as $a):$rule=json_decode((string)($a['compensation_snapshot']??''),true)?:[];$trigger=(string)($rule['eligibility_trigger']??'completed_approved');?><tr><td><strong><?=$h($a['job_code'])?></strong><small><?=$h($a['component_name'])?></small></td><td><?=$h($a['display_name']?:'Unassigned')?></td><td><?=$a['estimated_pay']!==null?'$'.number_format((float)$a['estimated_pay'],2):'—'?></td><td><?=$h(str_replace('_',' ',ucfirst($a['status'])))?></td><td class="text-right"><?php if($a['status']==='planned'):?><form method="post" action="/?page=settings/workforce-catalog-handler" class="inline-form"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="assignment-offer"><input type="hidden" name="return_tab" value="assignments"><input type="hidden" name="assignment_id" value="<?=(int)$a['id']?>"><select class="input input--small" name="worker_profile_id" required><option value="">Offer to…</option><?php foreach($workers as $w):?><option value="<?=(int)$w['id']?>"><?=$h($w['display_name'])?></option><?php endforeach;?></select><button class="btn btn-sm">Offer</button></form><?php elseif($a['status']==='completed'&&$trigger!=='invoice_paid'):?><form method="post" action="/?page=settings/workforce-catalog-handler" class="inline-form"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="assignment-eligible"><input type="hidden" name="return_tab" value="assignments"><input type="hidden" name="assignment_id" value="<?=(int)$a['id']?>"><input type="hidden" name="trigger_event" value="<?=$h($trigger)?>"><button class="btn btn-sm"><?=$trigger==='delivered'?'Confirm delivered':($trigger==='manual_release'?'Release compensation':'Review completed work')?></button></form><?php elseif($a['status']==='eligible'):?><form method="post" action="/?page=settings/workforce-catalog-handler" class="inline-form"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="assignment-approve"><input type="hidden" name="return_tab" value="assignments"><input type="hidden" name="assignment_id" value="<?=(int)$a['id']?>"><button class="btn btn-sm btn-primary">Approve payable</button></form><?php elseif($a['status']==='completed'&&$trigger==='invoice_paid'):?><span class="muted">Waiting for invoice payment</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$assignments):?><tr><td colspan="5">No assignments yet. Work components appear when catalog work is added to a Job.</td></tr><?php endif;?></tbody></table></div>
